 def lcs_length(s, t):
    from collections import Counter

    dp = Counter()

    for i in range(len(s)):
        for j in range(len(t)):
            if s[i] == t[j]:
                dp[(i, j)] = dp.get((i - 1, j), 0) + 1

    max_length = 0
    for length in dp.values():
        max_length = max(max_length, length)

    return max_length

